  }

  const nonNegativeMin = Math.max(min, 0);
  if (nonNegativeMin <= max) {
    parts.push(nonNegativeRange(nonNegativeMin, max));
  }

  return wrap(parts.join('|'));
}

export function rangeToRegexAnchored(min, max = min) {
  return `^(?:${rangeToRegex(min, max)})$`;
}

